define(['jquery', 'core/ajax', 'core/chartjs'], function($, Ajax, Chart) {
    let courseChart, enrolVsCompleteChart, data = {};



    function renderCourseChart(range, data) {
        if (courseChart) courseChart.destroy();

        let labels = [];
        let chartData = [];

        const rangeMap = {
            "1day": 0,
            "7day": 1,
            "30day": 2,
            "1year": 3
        };
        const idx = rangeMap[range];
        const dataset = data.courses?.[idx] || [];

        console.log("Rendering course chart for:", range, dataset);

        if (range === "1day") {
            let now = new Date(), h = now.getHours();
            for (let i = 0; i <= h; i++) {
                let hour = (i % 12 === 0) ? 12 : i % 12;
                let ampm = i < 12 ? "AM" : "PM";
                labels.push(hour + " " + ampm);
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "7day") {
            let today = new Date();
            for (let i = 0; i < 7; i++) {
                let d = new Date(today);
                d.setDate(today.getDate() - (6 - i));
                labels.push(d.toLocaleDateString("en-GB", { day: "2-digit", month: "short" }));
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "30day") {
            for (let i = 0; i < 4; i++) {
                labels.push("Week " + (i + 1));
                chartData.push(dataset[i] ?? 0);
            }

        } else if (range === "1year") {
            const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
            for (let i = 0; i < 12; i++) {
                labels.push(months[i]);
                chartData.push(dataset[i] ?? 0);
            }
        }

        const ctx = document.getElementById("courseChart").getContext("2d");
        const gradient = ctx.createLinearGradient(0,0,0,400);
        gradient.addColorStop(0,"rgba(54,162,235,0.9)");
        gradient.addColorStop(1,"rgba(54,162,235,0.2)");

        courseChart = new Chart(ctx, {
            type: "line",
            data: {
                labels: labels,
                datasets: [{
                    label: "Courses (" + range + ")",
                    data: chartData,
                    borderColor: "rgba(54,162,235,1)",
                    backgroundColor: gradient,
                    borderWidth: 2,
                    fill: true,
                    tension: 0.4,
                    pointBackgroundColor: "#36A2EB",
                    pointRadius: 4,
                    pointHoverRadius: 6
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { display: true }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        grid: { color: "rgba(200,200,200,0.2)" },
                        ticks: { color: "#444", font: { size: 12 } },
                        title: { display: true, text: "Courses Created", color: "#000" }
                    },
                    x: {
                        grid: { color: "rgba(200,200,200,0.1)" },
                        ticks: { color: "#444", font: { size: 12 } },
                        title: { display: true, text: range, color: "#000" }
                    }
                }
            }
        });
    }




    // ✅ Your doughnut chart function
   // ✅ Doughnut chart function for Enrol vs Complete
    function renderenrolVsCompleteChart(range, data) {
        if (enrolVsCompleteChart) enrolVsCompleteChart.destroy();

        // Make sure we pick correct structure
        const rangeMap1 = { "1day": "1day", "7day": "7day", "30day": "30day", "1year": "1year" };
        const enrolvscomplete = data.cards.enrolvscompletecourse?.[rangeMap1[range]] ?? { enrolled: 0, completed: 0 };

        let enrolled = enrolvscomplete.enrolled ?? 0;
        let completed = enrolvscomplete.completed ?? 0;

        let ctx = $('#enrolVsCompleteChart')[0].getContext('2d');

        // ✅ Create gradient colors
        let gradientEnrolled = ctx.createLinearGradient(0, 0, 0, 250);
        gradientEnrolled.addColorStop(0, "#C3F0CA");
        gradientEnrolled.addColorStop(1, "#2D6A4F");

        let gradientCompleted = ctx.createLinearGradient(0, 0, 0, 250);
        gradientCompleted.addColorStop(0, "#FDE68A");
        gradientCompleted.addColorStop(1, "#F59E0B");

        enrolVsCompleteChart = new Chart(ctx, {
            type: 'doughnut',
            data: {
                labels: ['Enrolled', 'Completed'],
                datasets: [{
                    data: [enrolled, completed],
                    backgroundColor: [gradientEnrolled, gradientCompleted],
                    borderWidth: 3,
                    borderColor: '#fff',
                    hoverOffset: 12
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                cutout: '82%',
                plugins: {
                    legend: {
                        position: 'bottom',
                        labels: {
                            color: '#374151',
                            font: { size: 14, weight: '600', family: "'Inter', sans-serif" },
                            usePointStyle: true,
                            pointStyle: 'circle',
                            padding: 18
                        }
                    },
                    tooltip: {
                        backgroundColor: '#111827',
                        titleColor: '#F9FAFB',
                        bodyColor: '#E5E7EB',
                        padding: 10,
                        cornerRadius: 8,
                        callbacks: {
                            label: function (context) {
                                let total = enrolled + completed;
                                let value = context.raw;
                                let percent = total > 0 ? ((value / total) * 100).toFixed(1) : 0;
                                return `${context.label}: ${value} (${percent}%)`;
                            }
                        }
                    }
                },
                animation: {
                    animateRotate: true,
                    animateScale: true,
                    duration: 1200,
                    easing: "easeOutQuart"
                }
            },
            plugins: [
                {
                    id: 'centerText',
                    beforeDraw: function(chart) {
                        let { width, height } = chart;
                        let ctx = chart.ctx;
                        ctx.restore();

                        // Main text (total learners)
                        ctx.font = "bold " + (height / 9) + "px 'Inter', sans-serif";
                        ctx.fillStyle = "#111827";
                        ctx.textBaseline = "middle";
                        let total = enrolled + completed;
                        let text = total + " Learners";
                        let textX = (width - ctx.measureText(text).width) / 2;
                        let textY = height / 2 - 10;
                        ctx.fillText(text, textX, textY);

                        // Subtext
                        ctx.font = "normal " + (height / 18) + "px 'Inter', sans-serif";
                        ctx.fillStyle = "#6B7280";
                        let subText = "Enrolled vs Completed";
                        let subTextX = (width - ctx.measureText(subText).width) / 2;
                        let subTextY = height / 2 + 30;
                        ctx.fillText(subText, subTextX, subTextY);

                        ctx.save();
                    }
                },
                {
                    id: 'shadowEffect',
                    beforeDatasetsDraw(chart) {
                        let ctx = chart.ctx;
                        ctx.save();
                        ctx.shadowColor = 'rgba(0,0,0,0.15)';
                        ctx.shadowBlur = 12;
                        ctx.shadowOffsetX = 0;
                        ctx.shadowOffsetY = 6;
                    },
                    afterDatasetsDraw(chart) {
                        chart.ctx.restore();
                    }
                }
            ]
        });
    }


    function loadData(range) {
        Ajax.call([{
            methodname: 'local_edzdashboardview_get_course_dashboard_data',
            args: { range: range }
        }])[0].done(function(resp) {
            data = resp;

            const rangeMap = { "1day":0, "7day":1, "30day":2, "1year":3 };
            const idx = rangeMap[range];
            const rangeMap1 = { "1day": "1day", "7day": "7day", "30day": "30day", "1year": "1year" };

            console.log("Course Tab Response:", resp);

            // ✅ Enrol vs complete card
            const enrolvscomplete = resp.cards.enrolvscompletecourse?.[rangeMap1[range]] ?? { enrolled: 0, completed: 0 };
            const totalEnrolvscomplete = (enrolvscomplete.enrolled ?? 0) + (enrolvscomplete.completed ?? 0);
            $('#card-enrolvscompleted').html(totalEnrolvscomplete);
             $('#card-enrolvscomplete-details').html("Enrolled: " + (enrolvscomplete.enrolled ?? 0) + ", Completed: " + (enrolvscomplete.completed ?? 0));

            // ✅ Total courses
            $('#card-coursescreate').html(resp.cards.courses?.[idx] ?? 0);

            // ============================================
            // ---- Top 5 Enrolled Courses ----
            // ============================================
            let topCourses = resp.cards.topcourses?.[rangeMap1[range]] ?? [];
            if (!Array.isArray(topCourses)) {
                topCourses = Object.values(topCourses);
            }

            // 👉 Update card with TOP course
            if (topCourses.length > 0) {
                let top = topCourses[0];
                $('#card-topcoursess').html(top.fullname ?? "N/A");
                $('#card-topcourses-detail').html("Enrolments: " + (top.total ?? 0));
                $('#card-topcourses-image').attr("src", top.image ?? "");
            } else {
                $('#card-topcoursess').html("No Data");
                $('#card-topcourses-detail').html("");
                $('#card-topcourses-image').attr("src", "");
            }

            // 👉 Build top courses table (responsive)
            let html = `
                <div class="table-responsive">
                    <table class="table table-hover table-bordered leaderboard-table mb-0">
                        <thead class="thead-light">
                            <tr>
                                <th class="text-center" style="width: 10%;">Rank</th>
                                <th style="width: 70%;">Course</th>
                                <th class="text-center" style="width: 20%;">Enrolments</th>
                            </tr>
                        </thead>
                        <tbody>
            `;

            if (topCourses.length === 0) {
                html += `<tr><td colspan="3" class="text-center">No data available</td></tr>`;
            } else {
                topCourses.slice(0, 5).forEach((course, i) => {
                    let image = course.image && course.image !== "" 
                        ? course.image 
                        : "/theme/image.php/boost/core/1/u/f1"; // fallback

                    html += `
                        <tr class="${i === 0 ? 'table-success' : ''}">
                            <td class="text-center"><strong>${i + 1}</strong></td>
                            <td>
                                <a href="${M.cfg.wwwroot}/course/view.php?id=${course.courseid}" target="_blank" class="d-flex align-items-center">
                                    <img src="${image}" class="rounded mr-2 flex-shrink-0" width="50" height="50" alt="${course.fullname}" />
                                    <span class="text-truncate d-inline-block" style="max-width: 200px;">${course.fullname}</span>
                                </a>
                            </td>
                            <td class="text-center"><strong>${course.total}</strong></td>
                        </tr>
                    `;
                });
            }

            html += `
                        </tbody>
                    </table>
                </div>
            `;

            $("#topcourseslist").html(html);


            // ============================================
            // ---- Top 5 Enrolled Categories ----
            // ============================================
            let topCategories = resp.cards.topcategories?.[rangeMap1[range]] ?? [];
            if (!Array.isArray(topCategories)) {
                topCategories = Object.values(topCategories);
            }

            // 👉 Update card with TOP category
            if (topCategories.length > 0) {
                let topCat = topCategories[0];
                $('#card-topcategoryinfo').html(topCat.categoryname ?? "N/A");
                $('#card-topcategory-detail').html("Enrolments: " + (topCat.total ?? 0));
                // $('#card-topcategory-image').attr("src", topCat.image ?? "");
            } else {
                $('#card-topcategoryinfo').html("No Data");
                $('#card-topcategory-detail').html("");
                $('#card-topcategory-image').attr("src", "");
            }

            // 👉 Build top categories table
            let catHtml = `
                <table class="table table-hover table-bordered leaderboard-table">
                    <thead>
                        <tr>
                            <th style="width: 10%; text-align:center;">Rank</th>
                            <th style="width: 70%;">Category</th>
                            <th style="width: 20%; text-align:center;">Enrolments</th>
                        </tr>
                    </thead>
                    <tbody>
            `;

            if (topCategories.length === 0) {
                catHtml += `<tr><td colspan="3" class="text-center">No data available</td></tr>`;
            } else {
                topCategories.slice(0, 5).forEach((cat, i) => {
                    catHtml += `
                        <tr class="${i === 0 ? 'table-success' : ''}">
                            <td class="text-center p-4"><strong>${i + 1}</strong></td>
                            <td class="p-4">${cat.categoryname}</td>
                            <td class="text-center p-4"><strong>${cat.total}</strong></td>
                        </tr>
                    `;
                });
            }

            catHtml += "</tbody></table>";
            $("#topcategorylist").html(catHtml);



           // ✅ Site Basic Info
            const siteInfo = resp.cards.dashboardtotalscount ?? {};

            // Fallbacks to 0 if null/undefined
            $('#total-badges').text(siteInfo.badges[idx] ?? 0);
            $('#total-forum').text(siteInfo.forum [idx]?? 0);
            $('#total-assignment').text(siteInfo.assignment[idx] ?? 0);
            $('#total-quizsubmitted').text(siteInfo.quizsub[idx]?? 0);
            $('#total-quizattempted').text(siteInfo.quizatt[idx] ?? 0);

            // ============================================
            // Render charts
            // ============================================
            renderCourseChart(range, data);
            renderenrolVsCompleteChart(range, data);
        });
    }


    return {
        init: function() {
            console.log("✅ course.js init called");
            loadData('1day');

            $('input[name="range-course"]').on('change', function() {
                let range = $(this).val();
                loadData(range);
            });
        }
    };
});
